<?php
require_once 'config/database.php';require_once 'includes/functions.php';$type=$_GET['type']??'';$sql="SELECT t.*,p.name product_name,p.sku FROM stock_transactions t JOIN products p ON p.id=t.product_id";$params=[];if(in_array($type,['masuk','keluar'],true)){$sql.=" WHERE t.type=?";$params[]=$type;}$sql.=" ORDER BY t.created_at DESC";$q=$pdo->prepare($sql);$q->execute($params);$rows=$q->fetchAll();$pageTitle='Riwayat Stok';require 'includes/header.php';?>
<div class="page-tools"><p class="muted">Riwayat seluruh aktivitas stok masuk dan keluar.</p><a class="btn btn-primary" href="stock.php">＋ Catat Stok</a></div>
<section class="panel"><div class="filter-tabs"><a class="<?= !$type?'selected':'' ?>" href="transactions.php">Semua</a><a class="<?= $type==='masuk'?'selected':'' ?>" href="transactions.php?type=masuk">Stok Masuk</a><a class="<?= $type==='keluar'?'selected':'' ?>" href="transactions.php?type=keluar">Stok Keluar</a></div><div class="table-wrap"><table><thead><tr><th>TANGGAL</th><th>PRODUK</th><th>JENIS</th><th>JUMLAH</th><th>CATATAN</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= date('d M Y, H:i',strtotime($r['created_at'])) ?></td><td><strong><?= e($r['product_name']) ?></strong><small class="table-sub"><?= e($r['sku']) ?></small></td><td><span class="type-pill <?= $r['type']==='masuk'?'type-in':'type-out' ?>"><?= ucfirst($r['type']) ?></span></td><td><strong class="<?= $r['type']==='masuk'?'positive':'negative' ?>"><?= $r['type']==='masuk'?'+':'-' ?><?= (int)$r['quantity'] ?></strong></td><td class="muted"><?= e($r['note']?:'-') ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5"><div class="empty-state compact">Belum ada riwayat stok.</div></td></tr><?php endif; ?></tbody></table></div><div class="table-foot">Total <?= count($rows) ?> aktivitas</div></section>
<?php require 'includes/footer.php'; ?>
